	@Test
	void checkedPilotProjectionCoversTwentyBillionTriples() {
		long targetVisits = LmdbAdjacencyMetrics.sourceVisitsForStatements(20_000_000_000L);
		long pilotVisits = LmdbAdjacencyMetrics.sourceVisitsForStatements(200_000_000L);
		long sixMinutes = TimeUnit.MINUTES.toNanos(6);

		assertThat(targetVisits).isEqualTo(80_000_000_000L);
		assertThat(LmdbAdjacencyMetrics.projectedBuildNanos(pilotVisits, sixMinutes, targetVisits))
				.isEqualTo(TimeUnit.HOURS.toNanos(10));
		assertThat(LmdbAdjacencyMetrics.projectedBuildNanos(0, sixMinutes, targetVisits)).isEqualTo(Long.MAX_VALUE);
		assertThat(LmdbAdjacencyMetrics.projectedBuildNanos(1, Long.MAX_VALUE, Long.MAX_VALUE))
				.isEqualTo(Long.MAX_VALUE);
	}

	private static BuildSnapshot build(int buildThreads) throws IOException {
		LmdbAdjacencyMemoryAccount account = new LmdbAdjacencyMemoryAccount(1L << 30);
		try (SingleStatementFamily family = new SingleStatementFamily();
				LmdbInMemoryAdjacencyIndex index = LmdbAdjacencyBaseBuilder.build(family,
						LmdbAdjacencyCoverage.full(), account, BASE_REGION_BYTES, WORKSPACE_REGION_BYTES,
						buildThreads)) {
			long outgoing = index.findRun(SUBJECT, LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, PREDICATE);
			long incoming = index.findRun(OBJECT, LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT, PREDICATE);
			assertThat(LmdbAdjacencyRunCodec.edgeCount(index.arenaCatalog(), outgoing)).isEqualTo(1);
			assertThat(LmdbAdjacencyRunCodec.edgeCount(index.arenaCatalog(), incoming)).isEqualTo(1);
			return new BuildSnapshot(outgoing, incoming, index.arenaCatalog().arena(0).capacityBytes(),
					index.statementCount(), index.incidenceCount());
		} finally {
			assertThat(account.totalChargedBytes()).isZero();
		}
	}

